TLM.f("Tempora/Nat2-0",{"officium":"Sanctissimi Nominis Jesu","rule":["Gloria","Credo","Prefatio=Nat"],"sections":{"Introitus":[{"k":"ref","la":"Phil 2:10-11"},{"k":"text","la":"In nómine Jesu omne genu flectátur, cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris"},{"k":"ref","la":"Ps 8:2"},{"k":"text","la":"Dómine, Dóminus noster, quam admirábile est nomen tuum in univérsa terra!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"In nómine Jesu omne genu flectátur, cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris"}],"Oratio":[{"k":"text","la":"Deus, qui unigénitum Fílium tuum constituísti humáni géneris Salvatórem, et Jesum vocári jussísti: concéde propítius; ut, cujus sanctum nomen venerámur in terris, ejus quoque aspéctu perfruámur in cœlis."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolorum"},{"k":"ref","la":"Act 4:8-12"},{"k":"text","la":"In diébus illis: Petrus, replétus Spíritu Sancto, dixit: Príncipes pópuli et senióres, audíte: Si nos hódie dijudicámur in benefácto hóminis infírmi, in quo iste salvus factus est, notum sit ómnibus vobis et omni plebi Israël: quia in nómine Dómini nostri Jesu Christi Nazaréni, quem vos crucifixístis, quem Deus suscitávit a mórtuis, in hoc iste astat coram vobis sanus. Hic est lapis, qui reprobátus est a vobis ædificántibus: qui factus est in caput ánguli: et non est in alio áliquo salus. Nec enim aliud nomen est sub cœlo datum homínibus, in quo opórteat nos salvos fíeri."}],"Graduale":[{"k":"ref","la":"Ps 105:47"},{"k":"text","la":"Salvos fac nos, Dómine, Deus noster, et cóngrega nos de natiónibus: ut confiteámur nómini sancto tuo, et gloriémur in glória tua."},{"k":"ref","la":"Isa 63:16"},{"k":"text","la":"Tu, Dómine, Pater noster et Redémptor noster: a sǽculo nomen tuum. Allelúja, allelúja"},{"k":"ref","la":"Ps 144:21"},{"k":"text","la":"Laudem Dómini loquétur os meum, et benedícat omnis caro nomen sanctum ejus. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 144:21"},{"k":"text","la":"Laudem Dómini loquétur os meum, et benedícat omnis caro nomen sanctum ejus. Allelúja."},{"k":"ref","la":"Ps 144:1"},{"k":"text","la":"Exaltábo te, Deus meus, Rex: et benedícam nómini sancto tuo, Jesu, in sǽculum, et in sǽculum sǽculi. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 79:20; Cant 2:14"},{"k":"text","la":"Dómine, Deus virtútum, convérte nos: et osténde fáciem tuam, et salvi érimus: sonet vox tua in áuribus meis. Vox enim tua dulcis, et fácies tua decóra nimis."},{"k":"ref","la":"Cant 1:2"},{"k":"text","la":"Oleum effúsum nomen tuum, Jesu: ideo adolescéntulæ dilexérunt te.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 2:21"},{"k":"text","la":"In illo témpore: Postquam consummáti sunt dies octo, ut circumciderétur Puer: vocátum est nomen ejus Jesus, quod vocátum est ab Angelo, priúsquam in útero conciperétur."}],"Offertorium":[{"k":"ref","la":"Ps 85:12; 85:5"},{"k":"text","la":"Confitébor tibi, Dómine, Deus meus, in toto corde meo, et glorificábo nomen tuum in ætérnum: quóniam tu, Dómine, suávis et mitis es: et multæ misericórdiæ ómnibus invocántibus te, allelúja."}],"Secreta":[{"k":"text","la":"Benedíctio tua, clementíssime Deus, qua omnis viget creatúra, sanctíficet, quǽsumus, hoc sacrifícium nostrum, quod ad glóriam nóminis Fílii tui, Dómini nostri Jesu Christi, offérimus tibi: ut majestáti tuæ placére possit ad laudem, et nobis profícere ad salútem."},{"k":"macro","name":"Per eumdem"}],"Communio":[{"k":"ref","la":"Ps 85:9-10"},{"k":"text","la":"Omnes gentes, quascúmque fecísti, vénient et adorábunt coram te, Dómine, et glorificábunt nomen tuum: quóniam magnus es tu et fáciens mirabília: tu es Deus solus, allelúja."}],"Postcommunio":[{"k":"text","la":"Omnípotens ætérne Deus, qui creásti et redemísti nos, réspice propítius vota nostra: et sacrifícium salutáris hóstiæ, quod in honórem nóminis Fílii tui, Dómini nostri Jesu Christi, majestáti tuæ obtúlimus, plácido et benígno vultu suscípere dignéris; ut grátia tua nobis infúsa, sub glorióso nómine Jesu, ætérnæ prædestinatiónis titulo gaudeámus nómina nostra scripta esse in cœlis."},{"k":"macro","name":"Per eumdem"}]},"hr":{"decdbdb49c54f664":{"t":"Phil 2, 10-11, Ps 8, 2\n(Fil 2, 10-11) Neka se u ime Isusovo pokloni svako koljeno onih koji su na nebu i na zemlji i pod zemljom, i svaki jezik neka prizna da je Gospodin Isus Krist u slavi Boga Oca. (Ps 8, 2) Gospodine, Gospodine Bože naš, kako je divno ime tvoje po svoj zemlji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Fil 2, 10-11) Neka se u ime Isusovo pokloni svako koljeno onih koji su na nebu i na zemlji i pod zemljom, i svaki jezik neka prizna da je Gospodin Isus Krist u slavi Boga Oca.","kn":"tJlaz (Fil. 2, 10-11). Da se u ime Isusovo pokloni svako koljeno onih, koji isu na nebu i na zemlji i pod zemljom i svaki jezik da prizna na slavu Bo.ga Oca: Isus Krist jest Gospodin. (Ps. 8, 2) Gosppdine, Gospodine naš, kako je divno ime Tvoje po isvoj zemlji! Slava Ocu . . . Da se u ime Isusovo . . .","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"7fed0c3da3b1a1bd":{"t":"<i>Pomolimo se</i>.\nBože, koji si jedinorođenoga Sina svoga postavio za Spasitelja ljudskom rodu i dao mu ime Isus. podaj milostivo da u nebu uživamo gledajući onoga, čije sveto ime častimo na zemlji.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si jedinorođenoga Sina Svoga postavio Spasiteljem ljudskom rodu i zapovjedio da se zove Isus, podaj milostivo^, da smijemo u nebu uživati gledajući Njega, kojega sveto ime častimo na zemlji, po istom G. n.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"ebc62128bc689a43":{"t":"Dj 4, 8-12\nČitanje Djela apostolskih: U one dane Petar, pun Duha Svetoga, progovori: Prvaci narodni i starješine, čujte! Pošto nam danas sudite zbog dobra, što smo ga učinili bolesnom čovjeku, znajte vi svi i sav izraelski narod kako je on ozdravio. U ime Isusa Krista Nazarećanina, što ste ga vi raspeli, a kojega je Bog uskrisio od mrtvih, po njemu ovaj stoji pred vama zdrav. To je onaj kamen što ste ga vi graditelji odbacili, a koji je postao ugaonim kamenom. I ni u kojem drugom nema spasa, jer je ljudima na zemlji dano samo ovo ime po kojem se mogu spasiti.","kn":"Čitanje Djela apostolskih (4, 8-12). U one se dane Petar napuni Duha Svetoga i progovori; Čujte, knezovi naroda i poglavari! Ako nas danas sudite radi dobra, koje smo učinili bolesnom čovjeku, znajte vi svi i sav izraelski puk, kako je om O'zdravio: U ime Isusa Krista Nazarećanina, kojega ste vi raspeli, a Bog ga je uskrisio od mrtvih, po njemu je ovaj pred vama zdrav. On je kamen, koji ste vi graditelji odbacili i koji je postao ugaoni kamen. I nema spasa ni u komu drugom, jer pod nebom nije ljudima dano drugo ime, po kojemu bi se mi mogli spasiti.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"ec95a37b56cc3070":{"t":"Ps 105, 47, Iz 63, 16\n(Ps 105, 47) Spasi nas, Gospodine Bože naš i skupi nas iz naroda, da slavimo ime tvoje i da se ponosimo slavom tvojom. (Iz 63,16) Ti si, Gospodine, otac naš i otkupitelj naš. Od vijeka je ime tvoje.\n\nPs 144, 21\n<i>Aleluja</i>, <i>aleluja</i>.\nNeka usta moja kazuju hvalu Gospodnju i neka svako tijelo blagosliva sveto ime njegovo. <i>Aleluja</i>.","kn":"(Ps. 105, 4, 7). Spasi nas. Gospodine, Bože naš, i skuipi nas iz naroda, da slavimo ime Tvoje, i ponosimo se u slavi Tvojoj. (laai 63, 16) Ti si, Gospodine, otac naš i otkupitelj naš, od vijeka je ime Tvoje.\n\nHvalu Gospodnju neka kazuju usta moja, i neka svaki čovjek blagosiva sveto ime njegovo. Aleluja.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"613f5280ca0f9775":{"t":"Lk 2, 21\nSlijedi sveto Evanđelje po Luki. U ono vrijeme, kad se navršilo osam dana da obrežu Dijete, dadu mu ime Isus, kao što ga je anđeo bio nazvao prije njegova začeća.","kn":"t Slijedi sveto Evanđelje po Luki (2, 21). U ono vrijeme, kad se navršilo osam dana, da obrežu dje. caka, dadoše mu ime Isus, kako Sa je anđeo bio nazvao prije začeća.","knRef":"Kniewald 1942, str. 66–67 (snimka 34) (OCR)"},"6dad051e7d99bac3":{"t":"Ps 85, 12 i 5\nSlavit ću te, Gospodine Bože moj, iz svega srca svojega i veličat ću ime tvoje u vijeke. Jer si ti, Gospodine, blag i krotak i pun milosrđa svima koji te zazivaju, <i>aleluja</i>.","kn":"(Ps. 85, 12, 5). Hvalit ću Te, Gospodine, Bože moj, i slavit ću ime Tvoje na vijeke, jer si Ti, Gospodine, blag i krotak i pun milosrđa za sve, koji Te prizivaju. Aleluja.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"ce609a47b000c321":{"t":"Blagoslov tvoj, preblagi Bože, koji daje snagu svakome stvoru, neka posveti, molimo, ovu žrtvu što ti je prinosimo na slavu imena tvojega Sina, Gospodina našega Isusa Krista, da uzmogne biti tvomu veličanstvu mila kao pohvala, a nama korisna za spasenje.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Blagoslov Tvoj, preblagi Bože, od kojega živi svako stvorenje, neka posveti, molimo, ovu našu žrtvu, što je Tebi prinosimo na slavu Sina Tvojega, Gospodina našega, Isusa Krista, da ova žrtva hvale bude ugodna Tvojemu veličanstvu a nama korisna za spasenje, po istom G. n.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"dec4b3da65ba38ea":{"t":"Ps 85, 9-10\nSvi narodi, što si ih stvorio, doći će i poklonit će se tebi, Gospodine, i slavit će ime tvoje, jer ti si velik i činiš čudesa. Ti si jedin Bog, <i>aleluja</i>.","kn":"(Ps. 85, 9, 10). Svi narodi, koje si stvo\" rio, doći će i ipoklonit će se pred Tobo-m, Gospodine, i slavit će ime Tvoje, jer Ti si velik, i činiš čudesa. Ti si jedini Bog, aleluja.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"},"b962ebbae90b27f4":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si nas stvorio i otkupio, obazri se milostivo na naše želje te se udostoj blaga i dobrostiva lica primiti prinos spasonosne žrtve što je tvojemu veličanstvu prikazasmo na čast imena tvojega Sina, Gospodina našega Isusa Krista, da se, primivši tvoju milost, radujemo što su naša imena upisana na nebesima pod slavnim Isusovim imenom, koje nam daje pravo na preodređenje za vječnost.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući, vječni Bože, koji si .nas stvorio 1 otkupio, pogledaj milostivo zavjete naše j blagim i dobrostivim licem obazri se na žrtvu spasonosnoga prinosa, što je prikazasmo na čast imena Sina Tvojega, Gospodina našega, Isusa Krista, i ulij u nas milost svoju, da se pod slavnim imenom Isusovim, jamstvom vječnoga predopredijeljenja, radujemo, što su naša imena upisana na nebesima. Po istom G. n, I. K.","knRef":"Kniewald 1942, str. 472–473 (snimka 237) (OCR)"}}});
